import type { FastifyInstance } from 'fastify';
import { createTestApp, resetDb } from '/app/tests/helpers/app.js';

const HOUR = 3_600_000;
const inHours = (h: number) => new Date(Date.now() + h * HOUR).toISOString();

describe('probe', () => {
  let app: FastifyInstance; let roomId: string; let userId: string;
  beforeAll(async () => { app = await createTestApp(); });
  afterAll(async () => { await app.close(); });
  beforeEach(async () => {
    await resetDb();
    roomId = (await app.inject({ method: 'POST', url: '/rooms', payload: { name: 'Aurora', capacity: 6 } })).json().id;
    userId = (await app.inject({ method: 'POST', url: '/users', payload: { name: 'Ada', email: 'a@e.com' } })).json().id;
  });
  const book = (s: number, e: number, title = 'X') => app.inject({ method: 'POST', url: '/bookings',
    payload: { roomId, userId, title, startsAt: inHours(s), endsAt: inHours(e) } });

  it('PROBE A: new booking starting BEFORE and ending INSIDE an existing one', async () => {
    await book(24, 25);
    const r = await book(23.5, 24.5, 'StraddleStart');
    console.log('A status:', r.statusCode);
    expect(r.statusCode).toBe(409);
  });

  it('PROBE B: new booking fully ENCLOSING an existing one', async () => {
    await book(24, 25);
    const r = await book(23, 26, 'Enclose');
    console.log('B status:', r.statusCode);
    expect(r.statusCode).toBe(409);
  });

  it('PROBE C: PATCH a booking into a conflicting slot', async () => {
    await book(24, 25);
    const second = await book(30, 31, 'Later');
    const r = await app.inject({ method: 'PATCH', url: `/bookings/${second.json().id}`,
      payload: { startsAt: inHours(24.5), endsAt: inHours(25.5) } });
    console.log('C status:', r.statusCode);
    expect(r.statusCode).toBe(409);
  });

  it('PROBE D: endsAt before startsAt', async () => {
    const r = await book(25, 24, 'Backwards');
    console.log('D status:', r.statusCode, JSON.stringify(r.json()));
    expect(r.statusCode).toBe(400);
  });

  it('PROBE E: booking against a room that does not exist', async () => {
    const r = await app.inject({ method: 'POST', url: '/bookings',
