import type { Booking, Prisma } from '@prisma/client';
import { prisma } from '../../db/client.js';
import type { Interval } from '../../shared/intervals.js';
import { BOOKING_ACTIVE } from './schema.js';

export interface BookingData {
  roomId: string;
  userId: string;
  title: string;
  startsAt: Date;
  endsAt: Date;
}

export interface BookingFilter {
  roomId?: string;
  userId?: string;
  status?: string;
  from?: Date;
  to?: Date;
  limit: number;
  offset: number;
}

export type SaveResult = { booking: Booking } | { conflict: Booking };

/**
 * Two bookings clash when they share any instant. Slots are half-open,
 * [startsAt, endsAt), so a booking may start exactly when another ends.
 */
function overlapWhere(
  roomId: string,
  startsAt: Date,
  endsAt: Date,
  excludeId?: string,
): Prisma.BookingWhereInput {
  return {
    roomId,
    status: BOOKING_ACTIVE,
    startsAt: { lt: endsAt },
    endsAt: { gt: startsAt },
    ...(excludeId ? { id: { not: excludeId } } : {}),
  };
}

/**
 * Writes the booking unless the room is already taken for the period. The check
 * and the write share one transaction so two concurrent requests for the same
 * slot cannot both pass the check.
 */
export function createIfFree(data: BookingData): Promise<SaveResult> {
  return prisma.$transaction(async (tx) => {
    const conflict = await tx.booking.findFirst({
      where: overlapWhere(data.roomId, data.startsAt, data.endsAt),
      orderBy: { startsAt: 'asc' },
    });
    if (conflict) return { conflict };
    return { booking: await tx.booking.create({ data }) };
  });
}

/** Same guarantee as {@link createIfFree}, ignoring the booking being moved. */
export function updateIfFree(
  id: string,
  data: Partial<BookingData>,
  slot: { roomId: string; startsAt: Date; endsAt: Date },
): Promise<SaveResult> {
  return prisma.$transaction(async (tx) => {
    const conflict = await tx.booking.findFirst({
      where: overlapWhere(slot.roomId, slot.startsAt, slot.endsAt, id),
      orderBy: { startsAt: 'asc' },
    });
    if (conflict) return { conflict };
    return { booking: await tx.booking.update({ where: { id }, data }) };
  });
}

/** Active bookings of the given rooms that touch the window, for slot maths. */
export async function findBusyIntervals(
  roomIds: string[],
  window: Interval,
  excludeId?: string,
): Promise<Map<string, Interval[]>> {
  const rows = await prisma.booking.findMany({
    where: {
      roomId: { in: roomIds },
      status: BOOKING_ACTIVE,
      startsAt: { lt: window.endsAt },
      endsAt: { gt: window.startsAt },
      ...(excludeId ? { id: { not: excludeId } } : {}),
    },
    select: { roomId: true, startsAt: true, endsAt: true },
    orderBy: { startsAt: 'asc' },
  });

  const byRoom = new Map<string, Interval[]>(roomIds.map((roomId) => [roomId, []]));
  for (const row of rows) {
    byRoom.get(row.roomId)?.push({ startsAt: row.startsAt, endsAt: row.endsAt });
  }
  return byRoom;
}

export function findById(id: string): Promise<Booking | null> {
  return prisma.booking.findUnique({ where: { id } });
}

export function list(filter: BookingFilter): Promise<[Booking[], number]> {
  const where: Prisma.BookingWhereInput = {};
  if (filter.roomId) where.roomId = filter.roomId;
  if (filter.userId) where.userId = filter.userId;
  if (filter.status) where.status = filter.status;
  if (filter.from) where.startsAt = { gte: filter.from };
  if (filter.to) where.endsAt = { lte: filter.to };

  return prisma.$transaction([
    prisma.booking.findMany({
      where,
      take: filter.limit,
      skip: filter.offset,
      orderBy: { startsAt: 'asc' },
    }),
    prisma.booking.count({ where }),
  ]);
}

export function updateStatus(id: string, status: string): Promise<Booking> {
  return prisma.booking.update({ where: { id }, data: { status } });
}

export function remove(id: string): Promise<Booking> {
  return prisma.booking.delete({ where: { id } });
}
EOF
