  // no-overlap rule as a fresh booking, measured against the resulting slot.
  const slot = {
    roomId: data.roomId ?? current.roomId,
    startsAt: data.startsAt ?? current.startsAt,
    endsAt: data.endsAt ?? current.endsAt,
