  assertOrderedRange(slot.startsAt, slot.endsAt);
  await assertRoomAndUserExist(data.roomId, data.userId);

  // A cancelled booking holds no slot, so moving it cannot clash with anything.
  if (current.status === BOOKING_CANCELLED) {
    return repository.updateStatus(id, current.status).then(() => repository.update(id, data));
