 * Offers the earliest slots of the requested length that the room really has,
 * so a rejected caller does not have to guess another time.
 */
async function suggestAlternatives(
  roomId: string,
  startsAt: Date,
  endsAt: Date,
  excludeId?: string,
): Promise<Interval[]> {
  const durationMs = endsAt.getTime() - startsAt.getTime();
  const window = { startsAt, endsAt: new Date(startsAt.getTime() + SUGGESTION_HORIZON_MS) };
  const busy = await repository.findBusyIntervals([roomId], window, excludeId);

  return freeSlots(window, busy.get(roomId) ?? [], durationMs)
    .slice(0, MAX_SUGGESTIONS)
    .map((slot) => ({
      startsAt: slot.startsAt,
      endsAt: new Date(slot.startsAt.getTime() + durationMs),
    }));
}
