import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'vitest';
import type { FastifyInstance } from 'fastify';
import { createTestApp, resetDb } from './helpers/app.js';

/** Fixed instants keep the expectations readable and independent of the clock. */
function at(hour: number): string {
  return new Date(Date.UTC(2030, 0, 1, hour)).toISOString();
}

describe('availability', () => {
  let app: FastifyInstance;
  let roomId: string;
  let boothId: string;
  let userId: string;

  beforeAll(async () => {
    app = await createTestApp();
  });

  afterAll(async () => {
    await app.close();
  });

  beforeEach(async () => {
    await resetDb();
    roomId = (
      await app.inject({ method: 'POST', url: '/rooms', payload: { name: 'Aurora', capacity: 6 } })
    ).json().id;
    boothId = (
      await app.inject({ method: 'POST', url: '/rooms', payload: { name: 'Booth', capacity: 2 } })
    ).json().id;
    userId = (
      await app.inject({
        method: 'POST',
        url: '/users',
        payload: { name: 'Ada Lovelace', email: 'ada@example.com' },
      })
    ).json().id;
  });

  async function book(startHour: number, endHour: number, title = 'Sync', room = roomId) {
    return app.inject({
      method: 'POST',
      url: '/bookings',
      payload: { roomId: room, userId, title, startsAt: at(startHour), endsAt: at(endHour) },
    });
  }

  function availability(room: string, query = ''): Promise<ReturnType<typeof app.inject>> {
    return app.inject({
      method: 'GET',
      url: `/rooms/${room}/availability?from=${at(8)}&to=${at(18)}${query}`,
    }) as Promise<ReturnType<typeof app.inject>>;
  }

  it('reports the whole window as free when nothing is booked', async () => {
    const response = await availability(roomId);
    expect(response.statusCode).toBe(200);
    expect(response.json().slots).toEqual([{ startsAt: at(8), endsAt: at(18) }]);
  });

  it('returns the gaps left between the bookings of a room', async () => {
    await book(9, 10, 'Standup');
    await book(14, 15, 'Retro');
    const response = await availability(roomId);
    expect(response.json().slots).toEqual([
      { startsAt: at(8), endsAt: at(9) },
      { startsAt: at(10), endsAt: at(14) },
      { startsAt: at(15), endsAt: at(18) },
    ]);
  });

  it('leaves no gap between bookings that touch', async () => {
    await book(9, 10, 'Standup');
    await book(10, 11, 'Review');
    const response = await availability(roomId);
    expect(response.json().slots).toEqual([
      { startsAt: at(8), endsAt: at(9) },
      { startsAt: at(11), endsAt: at(18) },
    ]);
  });

  it('clips bookings that run past the edges of the window', async () => {
    await book(6, 9, 'Early');
    await book(17, 20, 'Late');
    const response = await availability(roomId);
