describe('intervals', () => {
  const t = (hour: number): Date => new Date(Date.UTC(2030, 0, 1, hour));
  const span = (from: number, to: number): Interval => ({ startsAt: t(from), endsAt: t(to) });
  const readable = (intervals: Interval[]): string[] =>
    intervals.map((i) => `${i.startsAt.toISOString()}/${i.endsAt.toISOString()}`);

  it('merges overlapping intervals', () => {
    expect(readable(mergeIntervals([span(9, 11), span(10, 12)]))).toEqual(
      readable([span(9, 12)]),
    );
  });

  it('merges intervals that only touch', () => {
    expect(readable(mergeIntervals([span(9, 10), span(10, 11)]))).toEqual(
      readable([span(9, 11)]),
    );
  });

  it('keeps intervals that leave a gap apart', () => {
    expect(readable(mergeIntervals([span(9, 10), span(11, 12)]))).toEqual(
      readable([span(9, 10), span(11, 12)]),
    );
  });

  it('absorbs an interval contained in another', () => {
    expect(readable(mergeIntervals([span(9, 14), span(10, 11)]))).toEqual(
      readable([span(9, 14)]),
    );
  });

  it('sorts the input before merging', () => {
    expect(readable(mergeIntervals([span(14, 15), span(9, 10)]))).toEqual(
      readable([span(9, 10), span(14, 15)]),
    );
  });

  it('drops empty intervals', () => {
    expect(mergeIntervals([span(9, 9)])).toEqual([]);
  });

  it('returns the whole window when nothing is busy', () => {
    expect(readable(freeSlots(span(8, 18), []))).toEqual(readable([span(8, 18)]));
  });

  it('returns the gaps around the busy intervals', () => {
    expect(readable(freeSlots(span(8, 18), [span(9, 10), span(14, 15)]))).toEqual(
      readable([span(8, 9), span(10, 14), span(15, 18)]),
    );
  });

  it('clips busy intervals to the window', () => {
    expect(readable(freeSlots(span(8, 18), [span(6, 9), span(17, 20)]))).toEqual(
      readable([span(9, 17)]),
    );
  });

  it('ignores busy intervals outside the window', () => {
    expect(readable(freeSlots(span(8, 18), [span(2, 4)]))).toEqual(readable([span(8, 18)]));
  });

  it('returns nothing when the window is fully busy', () => {
    expect(freeSlots(span(8, 18), [span(7, 19)])).toEqual([]);
  });

  it('copes with busy intervals that overlap each other', () => {
    expect(readable(freeSlots(span(8, 18), [span(9, 12), span(10, 14)]))).toEqual(
      readable([span(8, 9), span(14, 18)]),
    );
  });

  it('drops the gaps shorter than the requested minimum', () => {
    const twoHours = 2 * 3_600_000;
    expect(readable(freeSlots(span(8, 18), [span(9, 10), span(11, 12)], twoHours))).toEqual(
      readable([span(12, 18)]),
    );
  });

  it('returns nothing for an empty window', () => {
    expect(freeSlots(span(8, 8), [])).toEqual([]);
  });
});
